      $logQ->execute([$targetId,'Merged duplicate service #'.$sid.' into this main service%']);
      if((int)$logQ->fetchColumn()<1)throw new RuntimeException('The matching merge audit record was not found; automatic recovery was stopped.');
      db()->beginTransaction();
      try{
        db()->prepare("UPDATE services SET ptero_server_id=NULL,ptero_identifier=NULL,status='pending',last_error=? WHERE id=?")
          ->execute(['Incorrect automatic duplicate merge undone. This service must be provisioned separately.',$targetId]);
        db()->prepare("UPDATE services SET ptero_server_id=?,ptero_identifier=?,status='active',last_error=NULL WHERE id=?")
          ->execute([(int)$target['ptero_server_id'],(string)($target['ptero_identifier']??''),$sid]);
        if(!empty($source['order_id']))db()->prepare("UPDATE orders SET status='active' WHERE id=?")->execute([(int)$source['order_id']]);
        if(!empty($target['order_id']))db()->prepare("UPDATE orders SET status='provisioning' WHERE id=?")->execute([(int)$target['order_id']]);
        db()->commit();
      }catch(Throwable $txe){
        if(db()->inTransaction())db()->rollBack();
        throw $txe;
      }
      $jid=provisioning_queue_service($targetId,['source'=>'undo_duplicate_merge','admin_id'=>(int)$u['id']],90,true);
      service_log($sid,(int)$u['id'],'merge_undone','Restored server link from incorrectly merged service #'.$targetId.'.');
      service_log($targetId,(int)$u['id'],'merge_undone','Returned server link to service #'.$sid.' and queued separate provisioning job #'.$jid.'.');
      $msg='Incorrect merge undone. Service #'.$sid.' was restored and service #'.$targetId.' was queued separately (job #'.$jid.').';
      break;
   case 'suspend': suspend_service($sid,(int)$u['id']);$msg='Service suspended.';break;
   case 'unsuspend': unsuspend_service($sid,(int)$u['id']);$msg='Service unsuspended.';break;
   case 'reinstall': reinstall_service($sid,(int)$u['id']);$msg='Reinstall requested.';break;
   case 'cancel': cancel_service($sid,(int)$u['id']);$msg='Service cancelled. The server was kept.';break;
   case 'reactivate': reactivate_service($sid,(int)$u['id']);$msg='Service reactivated.';break;
   case 'terminate': terminate_service($sid,(int)$u['id'],(string)($_POST['confirm_name']??''));$msg='Service permanently terminated.';break;
   case 'change_package':
    $pid=(int)($_POST['product_id']??0);$pq=db()->prepare('SELECT * FROM store_products WHERE id=?');$pq->execute([$pid]);$np=$pq->fetch();if(!$np)throw new RuntimeException('Product not found.');$sv=service_row($sid);$limits=['memory'=>(int)$np['ram_mb'],'disk'=>(int)$np['disk_mb'],'cpu'=>(int)$np['cpu_percent'],'backups'=>(int)$np['backups'],'databases'=>(int)$np['database_limit'],'allocations'=>(int)$np['allocation_limit']];if(!empty($sv['ptero_server_id']))ptero_apply_limits($sid,$limits);$cfg=json_decode((string)($sv['config_json']??''),true)?:[];$cfg=array_merge($cfg,['ram_mb'=>$limits['memory'],'disk_mb'=>$limits['disk'],'cpu_percent'=>$limits['cpu'],'backups'=>$limits['backups'],'database_limit'=>$limits['databases'],'allocation_limit'=>$limits['allocations']]);db()->prepare('UPDATE services SET product_id=?,price_monthly=?,config_json=? WHERE id=?')->execute([$pid,$np['price_monthly'],json_encode($cfg),$sid]);normalize_service_billing_schedule($sid);service_log($sid,(int)$u['id'],'change_package','Changed package to '.$np['name']);$msg='Package, billing schedule, and Pterodactyl limits updated.';break;
   case 'edit_resources':
    $sv=service_row($sid);$limits=['memory'=>max(128,(int)$_POST['ram_mb']),'disk'=>max(100,(int)$_POST['disk_mb']),'cpu'=>max(0,(int)$_POST['cpu_percent']),'backups'=>max(0,(int)$_POST['backups']),'databases'=>max(0,(int)$_POST['database_limit']),'allocations'=>max(1,(int)$_POST['allocation_limit'])];if(!empty($sv['ptero_server_id']))ptero_apply_limits($sid,$limits);$cfg=json_decode((string)($sv['config_json']??''),true)?:[];$cfg=array_merge($cfg,['ram_mb'=>$limits['memory'],'disk_mb'=>$limits['disk'],'cpu_percent'=>$limits['cpu'],'backups'=>$limits['backups'],'database_limit'=>$limits['databases'],'allocation_limit'=>$limits['allocations']]);db()->prepare('UPDATE services SET config_json=? WHERE id=?')->execute([json_encode($cfg),$sid]);service_log($sid,(int)$u['id'],'edit_resources','Resources updated from Admin Center.');$msg='Resources updated.';break;
   case 'extend_service':
    $sv=service_row($sid);if((float)$sv['price_monthly']<=0){normalize_service_billing_schedule($sid);throw new RuntimeException('Free services never expire and do not need an extension.');}$days=max(1,(int)($_POST['days']??30));db()->prepare("UPDATE services SET next_due_at=DATE_ADD(COALESCE(next_due_at,NOW()),INTERVAL ? DAY),cancel_at_period_end=0,cancel_at=NULL WHERE id=?")->execute([$days,$sid]);db()->prepare("INSERT INTO service_lifecycle(service_id,actor_user_id,event,details) VALUES(?,?, 'admin_extend',?)")->execute([$sid,$u['id'],'Extended by '.$days.' days']);service_log($sid,(int)$u['id'],'admin_extend','Extended service by '.$days.' days.');$msg='Service extended by '.$days.' days.';break;
   case 'set_due':
    $sv=service_row($sid);if((float)$sv['price_monthly']<=0){normalize_service_billing_schedule($sid);throw new RuntimeException('Free services never expire and cannot have a renewal date.');}$due=trim((string)($_POST['next_due_at']??''));$dueDate=DateTimeImmutable::createFromFormat('Y-m-d\TH:i',$due);if(!$dueDate||$dueDate->format('Y-m-d\TH:i')!==$due)throw new RuntimeException('Invalid renewal date and time.');$dueSql=$dueDate->format('Y-m-d H:i:s');db()->prepare('UPDATE services SET next_due_at=?,cancel_at=IF(cancel_at_period_end=1,?,cancel_at) WHERE id=?')->execute([$dueSql,$dueSql,$sid]);db()->prepare("INSERT INTO service_lifecycle(service_id,actor_user_id,event,details) VALUES(?,?, 'admin_due_date',?)")->execute([$sid,$u['id'],'Renewal date set to '.$dueSql]);service_log($sid,(int)$u['id'],'admin_due_date','Next due date changed to '.$dueSql.'.');$msg='Next due date updated.';break;
   case 'toggle_period_cancel':
    $sv=service_row($sid);if((float)$sv['price_monthly']<=0)throw new RuntimeException('Free services never expire. Cancel them directly if needed.');$on=!(bool)$sv['cancel_at_period_end'];db()->prepare('UPDATE services SET cancel_at_period_end=?,cancel_at=IF(?,next_due_at,NULL) WHERE id=?')->execute([$on?1:0,$on?1:0,$sid]);$msg=$on?'Cancellation scheduled.':'Scheduled cancellation removed.';break;
   case 'verify_link':
    $q=db()->prepare('SELECT ptero_server_id,ptero_identifier,name FROM services WHERE id=?');$q->execute([$sid]);$sv=$q->fetch();if(!$sv||!$sv['ptero_server_id'])throw new RuntimeException('This service has no Pterodactyl server linked.');
    $pj=app_ptero('/servers/'.(int)$sv['ptero_server_id']);$pa=$pj['attributes']??[];$actual=(string)($pa['identifier']??'');if($sv['ptero_identifier']&&$actual&&!hash_equals((string)$sv['ptero_identifier'],$actual))throw new RuntimeException('Pterodactyl identifier mismatch: expected '.$sv['ptero_identifier'].', got '.$actual);
    service_log($sid,(int)$u['id'],'verify_link','Pterodactyl link verified: server #'.$sv['ptero_server_id'].' '.$actual);$msg='Pterodactyl link verified for '.$sv['name'].'.';break;
   default: throw new RuntimeException('Unknown service action.');
  }
  zoho_crm_try_sync_service($sid);
 }catch(Throwable $e){if($sid>0&&ptero_deleted_server_error($e->getMessage())){clear_deleted_ptero_service_link_by_service_id($sid);$err=deleted_ptero_service_message();}else{$err=$e->getMessage();}}
}
